entries[7955] = { ["name"] = "Deviatschuppengürtel", ["text"] = "Wirken in 5 sek.\nReagenzien:\nPerfekte Deviatschuppe (6), Deviatschuppe (4), Feiner Faden (2)\nDeviatschuppengürtel\nWird beim Anlegen gebunden\nTaille Leder\n56 Rüstung\n+4 Beweglichkeit\n+5 Ausdauer\nErhöht Eure Trefferwertung um + 3.\nHaltbarkeit 40 / 40\n16" }
