entries[7979] = { ["name"] = "Kompakter Ernteschnitter", ["text"] = "Wirken in 2 sek.\nBeschwört 1 kompakten Ernteschnitter, um dem Zaubernden 1 Min. lang im Kampf zu helfen. Der Schnitter kann nicht geheilt werden, aber wenn er zerstört wird, kann er geplündert werden." }
entries[7992] = { ["name"] = "Verlangsamendes Gift", ["text"] = "30 Meter Reichweite\nWirken in 1 sek. 10 sek. Abklingzeit\nErhöht die Zeit zwischen Angriffen eines Gegners und verlangsamt sein Bewegungstempo. Hält 10 Sek. lang an." }
