entries[8000] = { ["name"] = "Flächenbrand", ["text"] = "160 Mana 30 Meter Reichweite\nWirken in 3 sek.\nLässt eine Flammensäule niedergehen, die alle Feinde in einem ausgewählten Gebiet verbrennt und ihnen zunächst 19 bis 21 Feuerschaden und dann zusätzlich 10 Sek. lang alle 3 Sek. 35 Schaden zufügt." }
