entries[8004] = { ["name"] = "Heilende Woge", ["text"] = "34.3% von Grundmana 40 Meter Reichweite\nWirken in 1.5 sek.\nHeilt ein befreundetes Ziel um 12519 ." }
entries[8014] = { ["name"] = "Tetanus", ["text"] = "Nahkampfreichweite\nSofort\nVerringert 15 Sek. lang die Ausdauer eines Feindes." }
entries[8016] = { ["name"] = "Stärkeverfall", ["text"] = "Nahkampfreichweite\nWirken in 2 sek.\nVerringert 15 Sek. lang die Stärke eines Feindes." }
entries[8017] = { ["name"] = "Waffe des Felsbeißers", ["text"] = "9.4% von Grundmana\nSofort\nBenötigt Nahkampfwaffe\nErfüllt die Waffe des Schamanen mit dem Zorn der Erde. Erhöht die gesamte Bedrohungserzeugung um 30% und verringert den erlittenen Schaden um 5%. Hält 60 Min. lang an. [ Elemente entfesseln : Das Entfesseln dieser Verzauberung zwingt das feindliche Ziel, den Schamanen 5 Sek. lang anzugreifen ]" }
entries[8024] = { ["name"] = "Waffe der Flammenzunge", ["text"] = "7% von Grundmana\nSofort\nBenötigt Nahkampfwaffe\nErfüllt die Waffe des Schamanen mit Feuermagie, die den verursachten Zauberschaden um 7% erhöht. Jeder Treffer verursacht zusätzlich 1 bis 1 Feuerschaden, abhängig vom Waffentempo. Langsamere Waffen verursachen pro Schwung mehr Feuerschaden. Hält 60 Minuten lang an. [ Elemente entfesseln : Das Entfesseln dieser Verzauberung fügt einem feindlichen Ziel 1241 Feuerschaden zu und erhöht den verursachten Schaden des nächsten Feuerzaubers des Schamanen um 30% ]" }
entries[8033] = { ["name"] = "Waffe des Frostbrands", ["text"] = "7% von Grundmana\nSofort\nBenötigt Nahkampfwaffe\nErfüllt die Waffe des Schamanen mit Frostmagie. Bei jedem Treffer besteht eine Chance, zusätzlich 42 Frostschaden zu verursachen und das Bewegungstempo des Ziels 8 Sek. lang um 50% zu verringern. Hält 60 Minuten lang an. [ Elemente entfesseln : Das Entfesseln dieser Verzauberung fügt einem gegnerischen Ziel 969 Frostschaden zu und verringert sein Bewegungstempo 5 Sek. lang um 50%. Der Effekt wird verstärkt, wenn das Ziel bereits von einem bewegungseinschränkenden Frosteffekt betroffen ist ]" }
entries[8034] = { ["name"] = "Frostbrandangriff", ["text"] = "100 Meter Reichweite\nSofort\nErfüllt die Waffe des Schamanen mit Frostmagie. Bei jedem Treffer besteht eine Chance, zusätzlich 42 Frostschaden zu verursachen und das Bewegungstempo des Ziels 8 Sek. lang um 50% zu verringern. Hält 60 Minuten lang an." }
entries[8040] = { ["name"] = "Druidenschlummer", ["text"] = "60 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nVersetzt das feindliche Ziel bis zu 6 Sek. lang in Schlaf. Jegliche feindliche Aktion wird das Ziel wieder aufwecken. Es kann immer nur jeweils ein Ziel in Schlaf versetzt werden." }
entries[8041] = { ["name"] = "Schlangenform", ["text"] = "Sofort\nErmöglicht 10 Sek. lang Gestaltwandlung in eine Schlange, erhöht körperlichen Schaden um 25, Zauber wirken ist allerdings nicht mehr möglich." }
entries[8042] = { ["name"] = "Erdschock", ["text"] = "14.4% von Grundmana 25 Meter Reichweite\nSofort 6 sek. Abklingzeit\nSchockt das Ziel sofort mit erschütternder Kraft, verursacht 1 Naturschaden und verursacht den Effekt 'Kampfesmüdigkeit'.\n\nKampfesmüdigkeit\nDemoralisiert das Ziel und verringert den von ihm verursachten körperlichen Schaden 30 Sek. lang um 10%." }
entries[8050] = { ["name"] = "Flammenschock", ["text"] = "11.9% von Grundmana 25 Meter Reichweite\nSofort 6 sek. Abklingzeit\nSchockt das Ziel unmittelbar mit sengendem Feuer, verursacht 1086 Feuerschaden und im Verlauf von 30 Sek. insgesamt weitere 10 Feuerschaden." }
