entries[8122] = { ["name"] = "Psychischer Schrei", ["text"] = "3% von Grundmana\nSofort 30 sek. Abklingzeit\nDer Zaubernde stößt einen psychischen Schrei aus, der 5 Gegner in einem Umkreis von 8 Metern 8 Sek. lang [ Glyphe 'Psychischer Schrei' : vor Furcht erstarren lässt / in die Flucht schlägt]. Erlittener Schaden kann den Effekt unterbrechen." }
entries[8129] = { ["name"] = "Manabrand", ["text"] = "14% von Grundmana 30 Meter Reichweite\nWirken in 2.5 sek.\nZerstört 10% des Manas des Ziels (bis zu höchstens 20% des maximalen Manas des Zaubernden). Für jeden Punkt auf diese Weise zerstörten Manas erleidet das Ziel 0,5 Punkte Schattenschaden." }
