entries[8143] = { ["name"] = "Totem des Erdstoßes", ["text"] = "2.3% von Grundmana\nSofort 1 min Abklingzeit\nBeschwört ein Erdtotem mit [ Glyphe 'Totemische Lebenskraft' : 5% der Gesundheit des Zaubernden zu dessen Füßen / 5 Gesundheit zu Füßen des Zaubernden], das 6 Sek. lang den Boden erschüttert und Furcht-, Schlaf- und Bezauberungseffekte von Gruppen- und Schlachtzugsmitgliedern im Umkreis von 30 Metern entfernt. Dieses Totem kann auch aufgestellt werden, wenn der Zaubernde von solchen Effekten betroffen ist." }
