entries[8151] = { ["name"] = "Überraschungs-Angriff", ["text"] = "Nahkampfreichweite\nSofort 30 sek. Abklingzeit\nFügt einem Feind normalen Schaden plus 28 bis 32 zu, wenn im Verstohlenheitsmodus angegriffen wird, und betäubt das Ziel 2.50 Sek. lang." }
entries[8152] = { ["name"] = "Schleichen", ["text"] = "Sofort 10 sek. Abklingzeit\nVersetzt den Zaubernden in den Verstohlenheitsmodus, verlangsamt aber sein Bewegungstempo um 50%. Hält an, bis die Aktion abgebrochen wird." }
entries[8153] = { ["name"] = "Eulengestalt", ["text"] = "Wirken in 5 sek.\nVerwandelt den Druiden in eine fliegende Gestalt und erhöht dadurch das Bewegungstempo." }
entries[8176] = { ["name"] = "Teufelsjäger beschwören", ["text"] = "Sofort\nBeschwört einen Wächterteufelsjäger, der Euch 1 Stunde lang beschützt." }
entries[8177] = { ["name"] = "Totem der Erdung", ["text"] = "5.9% von Grundmana\nSofort 25 sek. Abklingzeit\nBeschwört ein Lufttotem mit [ Glyphe 'Totemische Lebenskraft' : 5% der Gesundheit des Zaubernden zu dessen Füßen / 5 Gesundheit zu Füßen des Zaubernden], das [ Glyphe 'Totem der Erdung' : einen Schadenszauber, der auf ein nahes Gruppenmitglied gewirkt wird, auf den Zaubernden zurückschleudert / einen Schadenszauber, der auf ein nahes Gruppenmitglied gewirkt wird, auf sich selbst umlenkt], wobei das Totem zerstört wird. Wirkt nicht bei Flächenzaubern. Hält 15 Sek. lang an." }
entries[8178] = { ["name"] = "Totem der Erdung" }
