entries[8647] = { ["name"] = "Rüstung schwächen", ["text"] = "25 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nMacht eine Schwachstelle des Ziels ausfindig und belegt es mit [ Glyphe 'Rüstung schwächen' : 3 Stapeln des Effekts / dem Effekt] 'Rüstungsschwächung'. Gewährt 1 Combopunkt.\n\nRüstungsschwächung\nSchwächt die Rüstung des Ziels 30 Sek. lang um 4%. Bis zu 3-mal stapelbar." }
