entries[9206] = { ["name"] = "Schwärzlicher Gürtel", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nSchweres Leder (10), Seidenstoffballen (2), Schwarzer Farbstoff (2), Eiserne Gürtelschnalle\nSchwärzlicher Gürtel\nWird beim Anlegen gebunden\nTaille Leder\n87 Rüstung\n+8 Beweglichkeit\n+8 Ausdauer\nHaltbarkeit 40 / 40\n34" }
entries[9207] = { ["name"] = "Schwärzliche Stiefel", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nSchweres Leder (8), Schattenseide (2), Seidenfaden (2)\nSchwärzliche Stiefel\nWird beim Anlegen gebunden\nFüße Leder\n109 Rüstung\n+11 Beweglichkeit\n+3 Ausdauer\nHaltbarkeit 55 / 55\n35" }
entries[9208] = { ["name"] = "Hurtige Stiefel", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nSchweres Leder (10), Hurtigkeitstrank (2), Dicke Spinnenseide (2), Seidenfaden\nHurtige Stiefel\nWird beim Anlegen gebunden\nFüße Leder\n109 Rüstung\n+10 Ausdauer\nHaltbarkeit 55 / 55\n35\nBenutzen: Erhöht das Lauftempo 15 Sek. lang um 40%. (20 Min Abklingzeit)" }
