entries[9273] = { ["name"] = "Goblinüberbrückungskabel", ["text"] = "Wirken in 5 sek.\nReagenzien:\nEisenbarren (6), Surrendes bronzenes Dingsda (2), Fläschchen Öl (2), Seidenstoff (2), Schattenedelstein (2), Verschmorte Verkabelung\nBenötigt Ingenieurskunst\n(165)\nBenutzen: Mit Überbrückungskabeln kann man manchmal einen toten Verbündeten ins Leben zurückrufen. Kann nicht im Kampf verwendet werden. (30 Min Abklingzeit)" }
